const item = $input.item;

if (item.error) {
  return [{
    json: {
      status: "error",
      code: "DB_CONNECTION_FAILED",
      message: "Falha na conexão com o PostgreSQL sdtech_soluctions",
      error_details: item.error.message || "Erro desconhecido",
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    status: "success",
    code: "HEALTH_OK",
    message: "Conexão com PostgreSQL sdtech_soluctions estabelecida com sucesso",
    data: {
      database: item.json.database,
      user: item.json.db_user,
      server_time: item.json.server_time,
      pg_version: item.json.pg_version
    },
    timestamp: new Date().toISOString()
  }
}];
